def check_graph(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check degrees
    for i in range(n):
        if not (4 <= len(adj[i]) <= 7):
            return False, f"Node {i} has degree {len(adj[i])}"

    # Check girth
    for i in range(n):
        queue = [(i, 0)]
        visited = {i: 0}
        while queue:
            curr, dist = queue.pop(0)
            if dist >= 5: continue
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited[neighbor] = dist + 1
                    queue.append((neighbor, dist + 1))
                elif visited[neighbor] >= dist:
                    cycle_len = visited[neighbor] + dist + 1
                    if cycle_len <= 5:
                        return False, f"Cycle of length {cycle_len} found"
    return True, "OK"

